/** @description Owns health calls to the API service over the private binding. */

import { err, isErr, ok, tryAsync } from '@tenets/result';
import type { Result } from '@tenets/result';

import { parseApiServiceEnvironment } from './env';
import type { ApiServiceEnvironmentError } from './env';

/** @description Healthy view of the bound API service. */
export interface ApiHealth {
	readonly status: 'ok';
}

/** @description Recoverable reasons the API service is not observably healthy. */
export type ApiHealthError =
	| ApiServiceEnvironmentError
	| { readonly code: 'UPSTREAM_FAILURE'; readonly message: string };

/** @description Reads the service binding and checks the upstream API health contract. */
export async function getApiHealth({
	environment,
	fetcher = fetch,
}: {
	readonly environment: Readonly<Record<string, string | undefined>>;
	readonly fetcher?: typeof fetch;
}): Promise<Result<ApiHealth, ApiHealthError>> {
	const binding = parseApiServiceEnvironment(environment);
	if (isErr(binding)) {
		return binding;
	}

	const response = await tryAsync(
		() => fetcher(new URL('/api/health', binding.value.apiUrl), { cache: 'no-store' }),
		(): ApiHealthError => ({
			code: 'UPSTREAM_FAILURE',
			message: 'The API health check failed.',
		}),
	);
	if (isErr(response)) {
		return response;
	}

	if (!response.value.ok) {
		return err({ code: 'UPSTREAM_FAILURE', message: 'The API health check failed.' });
	}

	return ok({ status: 'ok' });
}

