/** @description Proves operational health calls through a deployment-aware service binding. */

import { err, ok } from '@tenets/result';
import { describe, expect, it, vi } from 'vitest';

import { getApiHealth } from './service-client';

describe('getApiHealth', () => {
	it('calls the private API health route', async () => {
		const fetcher = vi
			.fn<typeof fetch>()
			.mockResolvedValue(Response.json({ service: 'api', status: 'ok' }));

		await expect(
			getApiHealth({ environment: { API_URL: 'https://private-api.vercel.sh' }, fetcher }),
		).resolves.toEqual(ok({ status: 'ok' }));

		expect(fetcher).toHaveBeenCalledWith(new URL('https://private-api.vercel.sh/api/health'), {
			cache: 'no-store',
		});
	});

	it('reports a missing binding without throwing', async () => {
		await expect(getApiHealth({ environment: {} })).resolves.toEqual(
			err({
				code: 'MISSING_API_URL',
				message: 'API_URL is required. Run through Vercel Services or configure it locally.',
			}),
		);
	});

	it('reports a degraded upstream without throwing', async () => {
		const fetcher = vi
			.fn<typeof fetch>()
			.mockResolvedValue(new Response('unavailable', { status: 503 }));

		await expect(
			getApiHealth({ environment: { API_URL: 'https://private-api.vercel.sh' }, fetcher }),
		).resolves.toEqual(err({ code: 'UPSTREAM_FAILURE', message: 'The API health check failed.' }));
	});

	it('reports an unreachable upstream without throwing', async () => {
		const fetcher = vi.fn<typeof fetch>().mockRejectedValue(new Error('connection refused'));

		await expect(
			getApiHealth({ environment: { API_URL: 'https://private-api.vercel.sh' }, fetcher }),
		).resolves.toEqual(err({ code: 'UPSTREAM_FAILURE', message: 'The API health check failed.' }));
	});
});
